<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import UserForm from '@/components/UserForm.vue'; import { useUsersStore } from '@/stores/users'; import type { CreateUserDto, User } from '@/types/user'; const props = defineProps<{ id: string }>(), store = useUsersStore(), router = useRouter(), user = ref<User>(), error = ref(''); onMounted(async () => { try { user.value = await store.getById(Number(props.id)) } catch (e) { error.value = e instanceof Error ? e.message : 'Помилка' } }); async function submit(data: CreateUserDto) { try { await store.update(Number(props.id), data); router.push(`/users/${props.id}`) } catch (e) { error.value = e instanceof Error ? e.message : 'Помилка' } }</script>
<template><div class="page-heading"><div><p class="eyebrow">EDIT</p><h1>Редагування користувача</h1></div></div><div v-if="error" class="alert alert-danger">{{ error }}</div><UserForm v-if="user" :initial="user" submit-label="Зберегти" @submit="submit"/><div v-else class="status">Завантаження…</div></template>
